/* ns-newbdris-design.js — newbdris page, full screenshot design, client only.
   Rebuilt 2026-10-30 from the user's two screenshots, at their
   explicit instruction that NOTHING old should remain on this page:
   - Page background: light-blue gradient, like the screenshots.
   - FIRST: Autoload hero + Autoload card.
   - THEN: New-birth-registration hero + Personal-info card.
   - Blue gradient header bars (#2563eb -> #1e40af, exactly the
     screenshots' blue — this page only; the rest of the site
     keeps its teal).
   - Field icon chips, dashed upload box, full-width blue buttons,
     footer notes, and the "পেছনে যান" link, as in the screenshots.
   What is NOT changed, and why (these are functional, not design):
   - DOM order/count of .brn-grid inputs is NEVER changed: order
     submission and document auto-fill map fields by DOM index.
     Visual order is changed ONLY with CSS `order` on this page,
     to match the screenshots' field sequence as closely as the
     separate Upazila and Zila inputs allow (the screenshots show
     them combined in one line; this site has them as two
     separate inputs, so both stay, adjacent, with their own
     labels — merging them would send an empty Zila and break
     the order).
   - 2026-10-30 the user had the whole option card removed
     (see ns-bdris-clean.js): no option pills remain on this
     page. The order now always goes as নরমাল (800 টাকা),
     the option that was selected by default before removal.
   - The autoload "লোড করুন" button does NOT fetch government/
     BDRIS data and does NOT pretend to (no agreed external
     lookup exists). After the math captcha it pre-fills the BRN
     and DOB you typed into the personal-info fields below and
     scrolls there. The card states this plainly.
   - 2026-10-30 the user supplied the real banner artworks
     (no UI text): document + leaves + green check on the RIGHT
     of the autoload hero, baby + document + leaves + heart on
     the RIGHT of the new-birth hero; the two circular logos
     stay on the LEFT of each hero. Page order is unchanged
     and must stay that way: autoload hero + card FIRST (top),
     new-birth hero + personal-info card SECOND (below) —
     nothing is moved up or grouped together at the top. */
(function(){
  'use strict';
  function isNewBdris(){ return (location.hash || '').indexOf('newbdris') !== -1; }
  var captcha = {a: 0, b: 0};
  function newCaptcha(){
    captcha.a = 10 + Math.floor(Math.random() * 41);
    captcha.b = 10 + Math.floor(Math.random() * 41);
    var el = document.getElementById('nsAutoCaptchaImg');
    if (el) el.textContent = captcha.a + '+' + captcha.b + '=?';
    var t = document.getElementById('nsAutoCaptchaTxt');
    if (t) t.value = '';
  }
  function toDDMMYYYY(v){
    v = (v || '').trim();
    var m = v.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (m) return m[3] + '/' + m[2] + '/' + m[1];
    return v;
  }
  function fire(el){
    try { el.dispatchEvent(new Event('input', {bubbles: true})); } catch(e){}
    try { el.dispatchEvent(new Event('change', {bubbles: true})); } catch(e){}
  }
  function onLoad(){
    var brn = document.getElementById('nsAutoBrn');
    var dob = document.getElementById('nsAutoDob');
    var cap = document.getElementById('nsAutoCaptchaTxt');
    var msg = document.getElementById('nsAutoMsg');
    function say(txt, ok){
      if (!msg) return;
      msg.textContent = txt;
      msg.style.color = ok ? '#166534' : '#dc2626';
      msg.style.background = ok ? '#f0fdf4' : '#fef2f2';
    }
    if (!brn || !brn.value.trim()) { say('জন্ম নিবন্ধন নম্বর লিখুন।', false); return; }
    if (!dob || !dob.value.trim()) { say('জন্ম তারিখ লিখুন।', false); return; }
    if (!cap || parseInt(cap.value.trim(), 10) !== captcha.a + captcha.b) {
      say('ক্যাপচা উত্তর ভুল হয়েছে। নতুন ক্যাপচা দেওয়া হলো, আবার চেষ্টা করুন।', false);
      newCaptcha(); return;
    }
    var card = document.getElementById('brnCopyCard');
    if (!card) { say('ব্যক্তিগত তথ্যের ফর্ম পাওয়া যায়নি, পেজটি রিফ্রেশ করুন।', false); return; }
    var inputs = card.querySelectorAll('.brn-grid input, .brn-grid select, .brn-grid textarea');
    if (inputs[3]) { inputs[3].value = brn.value.trim(); fire(inputs[3]); }
    if (inputs[9]) { inputs[9].value = toDDMMYYYY(dob.value); fire(inputs[9]); }
    say('জন্ম নিবন্ধন নম্বর ও জন্ম তারিখ ব্যক্তিগত তথ্যে বসানো হয়েছে। বাকি তথ্য পূরণ করে অর্ডার করুন।', true);
    try { card.scrollIntoView({behavior: 'smooth', block: 'start'}); } catch(e){}
  }
  var DOC_ART = '<img class="ns-nb-hero-banner" src="data:image/jpeg;base64," alt="">';
  var BABY_ART = '<img class="ns-nb-hero-banner" src="data:image/jpeg;base64," alt="">';
  function build(){
    var main = document.getElementById('main');
    if (!main) return;
    if (!isNewBdris()){
      main.classList.remove('ns-nb-page');
      return;
    }
    main.classList.add('ns-nb-page');
    var card = document.getElementById('brnCopyCard');
    if (!card) return;
    // Personal-info hero + header bar, once.
    if (!card.classList.contains('ns-nb-design')) {
      card.classList.add('ns-nb-design');
      var hero2 = document.createElement('div');
      hero2.className = 'ns-nb-hero';
      hero2.innerHTML = '<div class="ns-nb-hero-text"><img class="ns-nb-hero-logo" src="data:image/png;base64," alt=""><div><b>নতুন জন্মনিবন্ধন</b><small>জন্ম নিবন্ধন করুন, নাগরিকত্বের প্রথম ধাপ</small><span>সঠিক তথ্য দিন, নিরাপদ থাকুন<br>আপনার শিশুর উজ্জ্বল ভবিষ্যৎ নিশ্চিত করুন।</span></div></div><div class="ns-nb-hero-art">' + BABY_ART + '</div>';
      card.parentNode.insertBefore(hero2, card);
      var head = document.createElement('div');
      head.className = 'ns-nb-head';
      head.innerHTML = '<span class="ns-nb-head-l">ব্যক্তিগত তথ্য</span><span class="ns-nb-head-r">সঠিক তথ্য দিন, দ্রুত সেবা নিন</span>';
      card.insertBefore(head, card.firstChild);
      // Upload box wording, as in the screenshot. The button's
      // onclick (document auto-fill) is untouched.
      var dash = card.querySelector('.brn-dash');
      if (dash) {
        var spans = dash.querySelectorAll('span');
        if (spans.length > 1) spans[spans.length - 1].innerHTML = 'স্বয়ংক্রিয়ভাবে আপলোড করুন<br>এখানে ক্লিক করুন';
      }
      // Footer note + back link, after the order button.
      var foot = document.createElement('div');
      foot.className = 'ns-nb-foot';
      foot.innerHTML = '<p class="ns-nb-note">🛡️ দ্রষ্টব্য: সকল তথ্য সঠিকভাবে প্রদান করুন। ভুল তথ্য দিলে আবেদন বাতিল হতে পারে।</p><p class="ns-nb-back"><a href="#/dashboard">← পেছনে যান</a></p>';
      card.appendChild(foot);
    }
    // FIX 2026-10-30 (user correction): the two sections must
    // stay SEPARATE, each banner with its own card, in order:
    // [autoload hero + card] FIRST, [new-birth hero + personal
    // card] SECOND. Previously hero2 was inserted before the
    // card and the autoload wrap was then inserted before the
    // same card, landing BETWEEN hero2 and its card — so both
    // headings sat at the top and the banners were detached
    // from their sections. If that wrong order already exists
    // (e.g. from a cached render), fix it here before returning.
    var existingWrap = document.getElementById('nsAutoCard');
    if (existingWrap) {
      var heroes = [];
      main.querySelectorAll('.ns-nb-hero').forEach(function(h){ if (!existingWrap.contains(h)) heroes.push(h); });
      if (heroes.length && existingWrap.nextElementSibling !== heroes[0]) main.insertBefore(existingWrap, heroes[0]);
      if (heroes.length && heroes[0].nextElementSibling !== card) card.parentNode.insertBefore(heroes[0], card);
      return;
    }
    var wrap = document.createElement('div');
    wrap.id = 'nsAutoCard';
    wrap.innerHTML =
      '<div class="ns-nb-hero"><div class="ns-nb-hero-text"><img class="ns-nb-hero-logo" src="data:image/png;base64," alt=""><div><b>অটোলোড তথ্য</b><small>Autoload Information</small><span>আপনার জন্ম নিবন্ধন নম্বর, জন্ম তারিখ ও ক্যাপচা পূরণ করে তথ্য দেখুন।</span></div></div><div class="ns-nb-hero-art">' + DOC_ART + '</div></div>'
      + '<div class="ns-auto-card">'
      + '<div class="ns-auto-bar"><span>তথ্য প্রদান করুন</span><span class="ns-auto-bar-r">সঠিক তথ্য দিন, দ্রুত সেবা নিন</span></div>'
      + '<div class="ns-auto-body">'
      + '<div class="ns-auto-field"><span class="ns-auto-fico">🪪</span><div class="ns-auto-fmain"><label class="ns-auto-label">জন্ম নিবন্ধন নম্বর *</label><input id="nsAutoBrn" class="ns-auto-input" placeholder="XXXXXXXXXXXXXXXXX" inputmode="numeric"></div></div>'
      + '<div class="ns-auto-field"><span class="ns-auto-fico">📅</span><div class="ns-auto-fmain"><label class="ns-auto-label">জন্ম তারিখ *</label><div class="ns-auto-with-ico"><input id="nsAutoDob" class="ns-auto-input" placeholder="YYYY-MM-DD"><span class="ns-auto-in-ico">📅</span></div></div></div>'
      + '<div class="ns-auto-field"><span class="ns-auto-fico">🛡️</span><div class="ns-auto-fmain"><label class="ns-auto-label">ক্যাপচা ছবি *</label><div class="ns-auto-cap-row"><span id="nsAutoCaptchaImg" class="ns-auto-cap-img"></span><button type="button" id="nsAutoCapRefresh" class="ns-auto-cap-refresh">↻ নতুন ক্যাপচা</button></div></div></div>'
      + '<div class="ns-auto-field"><span class="ns-auto-fico">⌨️</span><div class="ns-auto-fmain"><label class="ns-auto-label">ক্যাপচা টেক্সট *</label><input id="nsAutoCaptchaTxt" class="ns-auto-input" placeholder="XX" inputmode="numeric"></div></div>'
      + '<button type="button" id="nsAutoLoadBtn" class="ns-auto-btn">➤ লোড করুন</button>'
      + '<p id="nsAutoMsg" class="ns-auto-msg"></p>'
      + '<p class="ns-auto-note">ⓘ ইশিত: সঠিক তথ্য প্রদান করুন, অন্যথায় তথ্য পাওয়া যাবে না। এই লোড বোতামটি আপনার লেখা নম্বর ও তারিখ নিচের ব্যক্তিগত তথ্যে বসিয়ে দেয়; সরকারি ডাটাবেস থেকে কোনো তথ্য আনা হয় না।</p>'
      + '</div></div>';
    var firstCard = main.querySelector('.card');
    // Insert BEFORE the new-birth hero (which sits directly
    // before the personal card), not before the card itself —
    // otherwise the wrap lands between hero2 and its card.
    var heroBeforeCard = card.previousElementSibling;
    if (heroBeforeCard && heroBeforeCard.classList.contains('ns-nb-hero')) main.insertBefore(wrap, heroBeforeCard);
    else if (firstCard) main.insertBefore(wrap, firstCard); else main.insertBefore(wrap, card);
    newCaptcha();
    var loadBtn = document.getElementById('nsAutoLoadBtn');
    if (loadBtn) loadBtn.addEventListener('click', onLoad);
    var refresh = document.getElementById('nsAutoCapRefresh');
    if (refresh) refresh.addEventListener('click', function(e){ e.preventDefault(); newCaptcha(); });
  }
  /* ---- 2026-10-31 reference redesign (first reference image) ----
     Page furniture only; prices, field order and order submission
     are untouched (see ns-bdris-clean.js header for why prices
     stay the site's own, not the reference's 780/1920).
     - Page title + page notice bar at the top of this page.
     - Type cards (#nsTypeCard > #opts .opt) just before the
       new-birth hero, so the order follows the selected type
       again via ns-bdris-clean.js's selectedOption().
     - Order-history section (#nsOrderHistory) after the personal
       card, rendered from NS_STATE.orders (newbdris only) with
       client-side search, show-entries and pagination.
     - Page-only ticker: the existing header ticker's TEXT is
       replaced with this page's headline while on newbdris and
       restored when leaving — NO second ticker is ever created.
     - NOT copied from the reference: the other site's circular
       seal logo, its phone number, and its form-textarea template
       (fields stay the site's own brn fields, which the order
       payload maps by DOM index). Type card artwork is an original
       teal gradient + NS badge. */
  var PAGE_HEADLINE = 'অর্ডার করার আগে অবশ্যই ইনবক্সে কথা বলে অর্ডার করুন ধন্যবাদ 🥰। ২০০৭/২০০৮ এ মেয়েদের কাজ বন্ধ ❌';
  var TYPES = [
    { name: 'নরমাল', price: '800' },
    { name: 'পসিবল', price: '800' },
    { name: 'মিনিস্ট্রি', price: '1000' },
    { name: 'CTG নরমাল', price: '2000' }
  ];
  var histPage = 1, histSearch = '', histShow = 10;
  function fmtCreated(c) {
    c = c || ''; if (c.indexOf('T') !== -1) c = c.slice(0, 16).replace('T', ' ');
    return c;
  }
  function histRows() {
    var all = [];
    try { if (typeof NS_STATE !== 'undefined' && NS_STATE && Array.isArray(NS_STATE.orders)) all = NS_STATE.orders; } catch (e) {}
    var rows = all.filter(function (o) { return o && o.service_id === 'newbdris'; });
    if (histSearch) {
      var q = histSearch.toLowerCase();
      rows = rows.filter(function (o) {
        return String(o.id || '').toLowerCase().indexOf(q) !== -1 ||
          String(o.status || '').toLowerCase().indexOf(q) !== -1 ||
          String(o.amount_bdt || '').indexOf(q) !== -1;
      });
    }
    return rows;
  }
  function renderHist() {
    var body = document.getElementById('nsHistBody');
    var foot = document.getElementById('nsHistFoot');
    if (!body) return;
    var rows = histRows();
    var total = rows.length;
    var pages = Math.max(1, Math.ceil(total / histShow));
    if (histPage > pages) histPage = pages;
    var start = total ? (histPage - 1) * histShow + 1 : 0;
    var end = Math.min(total, histPage * histShow);
    var page = rows.slice((histPage - 1) * histShow, histPage * histShow);
    /* FREEZE FIX 2026-10-31: this runs on every #main mutation, so
       writing innerHTML unconditionally re-fired the observer and
       looped forever, freezing clicks/navigation on this page.
       Now nothing is written unless it actually changed. */
    var html;
    if (!page.length) {
      html = '<tr><td colspan="6" class="ns-hist-empty">No data available in table</td></tr>';
    } else {
      html = page.map(function (o) {
        return '<tr><td data-label="NO">' + (o.id || '') + '</td><td data-label="COST">' + (o.amount_bdt || '') + ' টাকা</td><td data-label="STATUS">' + (o.status || '') + '</td><td data-label="SYNC">—</td><td data-label="CREATED">' + fmtCreated(o.created_at) + '</td><td data-label="ACTION">—</td></tr>';
      }).join('');
    }
    if (body.innerHTML !== html) body.innerHTML = html;
    var footTxt = 'Showing ' + start + ' to ' + end + ' of ' + total + ' entries';
    if (foot && foot.textContent !== footTxt) foot.textContent = footTxt;
    var pv = document.getElementById('nsHistPrev'), nx = document.getElementById('nsHistNext');
    if (pv && pv.disabled !== (histPage <= 1)) pv.disabled = histPage <= 1;
    if (nx && nx.disabled !== (histPage >= pages)) nx.disabled = histPage >= pages;
  }
  function setTicker(page) {
    var texts = document.querySelectorAll('#nsTicker .ns-ticker-text');
    if (!texts.length) return;
    if (page) {
      if (!window._nsNbTickerOn) {
        window._nsNbTickerOrig = [texts[0].textContent, texts.length > 1 ? texts[1].textContent : ''];
        window._nsNbTickerOn = true;
      }
      texts.forEach(function (el) { if (el.textContent !== PAGE_HEADLINE) el.textContent = PAGE_HEADLINE; });
    } else if (window._nsNbTickerOn) {
      if (texts[0] && window._nsNbTickerOrig) texts[0].textContent = window._nsNbTickerOrig[0];
      if (texts[1] && window._nsNbTickerOrig) texts[1].textContent = window._nsNbTickerOrig[1];
      window._nsNbTickerOn = false;
    }
  }
  function buildRef() {
    try {
      if (!isNewBdris()) { setTicker(false); return; }
      setTicker(true);
      var main = document.getElementById('main');
      var card = document.getElementById('brnCopyCard');
      if (!main || !card) return;
      /* HEADLINE FIX 2026-10-31: only ONE headline on this page —
         the header ticker, whose text becomes PAGE_HEADLINE here
         and is restored elsewhere (setTicker). The page notice bar
         duplicated the same headline, so it is removed, not added.
         The page keeps only its title. */
      var oldTitle = document.getElementById('nsNbPageTitle');
      if (oldTitle) {
        var oldNotice = oldTitle.querySelector('.ns-nb-page-notice');
        if (oldNotice) oldNotice.remove();
      } else {
        var title = document.createElement('div');
        title.id = 'nsNbPageTitle';
        title.innerHTML = '<h2>নতুন জন্ম নিবন্ধন অর্ডার</h2>';
        main.insertBefore(title, main.firstChild);
      }
      if (!document.getElementById('nsTypeCard')) {
        var tc = document.createElement('div');
        tc.id = 'nsTypeCard'; tc.className = 'card';
        var grid = TYPES.map(function (ty, i) {
          return '<div class="opt' + (i === 0 ? ' sel' : '') + '" data-name="' + ty.name + '" data-price="' + ty.price + '"><div class="ns-type-img"><span class="ns-type-badge">NS</span></div><div class="ns-type-name">🌟 ' + ty.name + ' 🌟</div><div class="ns-type-price">(' + ty.price + ' টাকা)</div></div>';
        }).join('');
        tc.innerHTML = '<div class="ns-type-label">Type <span>*</span></div><div id="opts" class="ns-type-grid">' + grid + '</div><p id="nsBdrisTotal" class="ns-type-total">এটি অর্ডার করতে আপনার অ্যাকাউন্ট থেকে নরমাল (800 টাকা) কাটা হবে।</p>';
        var hero = card.previousElementSibling;
        if (hero && hero.classList.contains('ns-nb-hero')) card.parentNode.insertBefore(tc, hero);
        else card.parentNode.insertBefore(tc, card);
        tc.querySelectorAll('#opts .opt').forEach(function (opt) {
          opt.addEventListener('click', function () {
            tc.querySelectorAll('#opts .opt').forEach(function (o) { o.classList.remove('sel'); });
            opt.classList.add('sel');
            var tot = document.getElementById('nsBdrisTotal');
            var txt = 'এটি অর্ডার করতে আপনার অ্যাকাউন্ট থেকে ' + opt.getAttribute('data-name') + ' (' + opt.getAttribute('data-price') + ' টাকা) কাটা হবে।';
            if (tot) tot.textContent = txt;
            var notice = card.querySelector('p.notice');
            if (notice) notice.textContent = opt.getAttribute('data-name') + ' (' + opt.getAttribute('data-price') + ' টাকা) অনুযায়ী অ্যাকাউন্ট থেকে কাটা হবে।';
          });
        });
      }
      if (!document.getElementById('nsOrderHistory')) {
        var hs = document.createElement('div');
        hs.id = 'nsOrderHistory'; hs.className = 'card';
        hs.innerHTML = '<h2>অর্ডার ইতিহাস</h2><div class="ns-hist-controls"><label>Show <select id="nsHistShow"><option value="10" selected>10</option><option value="25">25</option><option value="50">50</option></select> entries</label><label>Search: <input id="nsHistSearch" type="search" placeholder=""></label></div><div class="ns-hist-wrap"><table><thead><tr><th>NO</th><th>COST</th><th>STATUS</th><th>SYNC</th><th>CREATED</th><th>ACTION</th></tr></thead><tbody id="nsHistBody"></tbody></table></div><div class="ns-hist-foot"><span id="nsHistFoot"></span><span><button type="button" id="nsHistPrev">Previous</button> <button type="button" id="nsHistNext">Next</button></span></div>';
        main.appendChild(hs);
        var si = document.getElementById('nsHistSearch');
        if (si) si.addEventListener('input', function () { histSearch = si.value.trim(); histPage = 1; renderHist(); });
        var ss = document.getElementById('nsHistShow');
        if (ss) ss.addEventListener('change', function () { histShow = parseInt(ss.value, 10) || 10; histPage = 1; renderHist(); });
        var pv = document.getElementById('nsHistPrev');
        if (pv) pv.addEventListener('click', function () { if (histPage > 1) { histPage--; renderHist(); } });
        var nx = document.getElementById('nsHistNext');
        if (nx) nx.addEventListener('click', function () { histPage++; renderHist(); });
      }
      renderHist();
    } catch (e) {}
  }
  function apply(){
    try { build(); } catch(e){}
    try { buildRef(); } catch(e){}
  }
  apply();
  /* Page-headline guard: the global ticker's notices fetch can land
     after buildRef() runs on a direct load, so re-assert the page
     headline every 3s while on this page. Text is only written
     when it differs, so there is no flicker or loop. */
  setInterval(function(){ try { if (isNewBdris()) setTicker(true); } catch(e){} }, 3000);
  window.addEventListener('hashchange', function(){ setTimeout(apply, 100); });
  var mainEl = document.getElementById('main');
  if (mainEl && typeof MutationObserver !== 'undefined') {
    // Idempotent only: build() returns early when its elements
    // exist, and creates nothing when they do — no self-loop.
    new MutationObserver(function(){ apply(); }).observe(mainEl, {childList: true, subtree: true});
  }
})();
